CREATE TABLE IF NOT EXISTS vault(name TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_states(state TEXT PRIMARY KEY,owner TEXT NOT NULL,verifier TEXT NOT NULL,client TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,metadata TEXT NOT NULL,media_key TEXT UNIQUE NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,due INTEGER NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL,video_id TEXT,upload_session TEXT,note TEXT);
CREATE INDEX IF NOT EXISTS jobs_due ON jobs(status,due);
CREATE TABLE IF NOT EXISTS skincare_launch_v2(id TEXT PRIMARY KEY,domain TEXT NOT NULL,format TEXT NOT NULL,due INTEGER NOT NULL,media_path TEXT NOT NULL,sha256 TEXT NOT NULL,thumbnail_path TEXT NOT NULL,thumbnail_sha256 TEXT NOT NULL,metadata TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'READY',video_id TEXT,note TEXT);
